WITH valid AS (SELECT id, order_id, product_id, quantity, unit_price, quantity + unit_price AS line_total FROM order_items WHERE unit_price > 390) SELECT product_id, CASE WHEN unit_price >= 420 THEN 'PREMIUM' ELSE 'STANDARD' END AS unit_price_tier, BIT_OR(quantity) AS quantity_bit_or, APPROX_PERCENTILE(unit_price, 0.9) AS unit_price_p90, ROUND(AVG(line_total), 2) AS avg_line_total, PERCENTILE_APPROX(line_total, 0.95) AS line_total_p95 FROM valid GROUP BY product_id, CASE WHEN unit_price >= 420 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY line_total_p95 DESC
